update lessons set objective_ar='أحلّل حكاية «الحوض المسحور» الشعبية الإماراتية إلى عناصرها، وأحلّل شخصياتها واختياراتها وعواقبها، وأستنتج وظيفتها التربوية، وأوازنها بحكاية شعبية أخرى.' where code='AR-Y8-N-T2-L18';
update success_criteria set statement_ar='أحدّد عناصر الحكاية الشعبية (الخروفة) وأحداثها.' where sort_order=1 and lesson_id=(select id from lessons where code='AR-Y8-N-T2-L18');
update success_criteria set statement_ar='أحلّل موقفي فطيم وحمد من نصيحة الشيخ وعاقبة كلٍّ منهما.' where sort_order=2 and lesson_id=(select id from lessons where code='AR-Y8-N-T2-L18');
update success_criteria set statement_ar='أستنتج الوظيفة التربوية للحكاية وأوازنها بحكاية «غولة النهر».' where sort_order=3 and lesson_id=(select id from lessons where code='AR-Y8-N-T2-L18');
update lesson_summaries set content=content||'{"emoji": "🦌", "hook": "حوض ماء في الصحراء… والشيخ يحذّر: لا تشربا حتى الشبع! فمن يستمع؟", "idea": "حكاية شعبية إماراتية ترويها الجدّة عن الأخوين فطيم وحمد: خالف حمد نصيحة الشيخ فشرب من الحوض المسحور حتى الارتواء فتحوّل إلى غزال، وصبرت فطيم حتى انكشفت الحقيقة.", "learn": [["📖", "أقرأ الحكاية في كتابي ص 212–222."], ["🍲", "يأكل الغراب «الكامي» فيضلّ الأخوان الطريق بحثًا عن بديل."], ["⚠️", "الشيخ ينصحهما: لا تشربا من الحوض حتى الشبع."], ["🦌", "حمد يخالف فيتحوّل إلى غزال، وفطيم تستمع."], ["👵", "العبرة: مخالفة نصائح الوالدين تؤدّي إلى المتاعب."]], "quiz": [["استمعت فطيم إلى نصيحة الشيخ فلم تُكثر من الشرب.", true], ["تحوّل حمد إلى غزال لأنه أكل «الكامي».", false]], "words": [["مَسْحور", "فيه قوة عجيبة"], ["النَّصيحَة", "إرشاد إلى ما فيه الخير"], ["الْخُرّوفَة", "الحكاية الشعبية في الإمارات"], ["الْعاقِبَة", "نتيجة الفعل"]], "think": "متى استمعتُ إلى نصيحة كبيرٍ فنجوت من مشكلة؟"}'::jsonb where lesson_id=(select id from lessons where code='AR-Y8-N-T2-L18');